check('the email is logged', (int) val("SELECT COUNT(*) FROM {email_log} WHERE event='pdf.export' AND status='sent'") === 1); putenv('MFNC_MAIL_DRYRUN'); set_setting('email_enabled', '0'); throws(fn() => do_pdf_email($upo), 'not set up', 'emailing explains when email is off');
$pf = $CU('pdf-free@x.test'); $upf = one('SELECT * FROM {users} WHERE id=?', [$pf]); $_POST = ['kind' => 'report', 'month' => $mo]; throws(fn() => do_pdf_email($upf), 'paid plan', 'a free-plan user cannot email a PDF'); throws(fn() => do_pdf_link($upf), 'paid plan', 'or make a link');

section('Payment page template');
$adm = $CU('pay-admin@x.test', 'Pay Admin'); run("UPDATE {users} SET role='admin' WHERE id=?", [$adm]); $uadm = one('SELECT * FROM {users} WHERE id=?', [$adm]);
$bad = '<div onclick="x()" style="color:red;background:url(javascript:alert(1));position:fixed"><script>alert(1)</script><p onmouseover="a()" class="ok x">Hi<img src="x" onerror="alert(1)"><a href="javascript:alert(1)">bad</a><a href="  JaVaScRiPt:alert(1)">bad2</a><a href="https://ok.example/x">fine</a></p><iframe src="https://evil.example"></iframe><form action="https://evil.example"><input name="amount" value="1"><button>Go</button></form><svg onload="x()"></svg><style>body{display:none}</style><!-- c --><img src="data:text/html;base64,PHNjcmlwdD4="><img src="data:image/png;base64,iVBORw0KGgo="><object data="x"></object><foo>kept text</foo>{total_payable}</div>';
$safe = paypage_sanitize($bad);
foreach (['<script', 'onclick', 'onerror', 'onmouseover', 'javascript:', '<iframe', '<form', '<input', '<button', '<svg', '<style', '<object', 'position', 'url(', '<!--', 'text/html', '<foo'] as $needle) { check("sanitiser strips: $needle", stripos($safe, $needle) === false); }
check('safe parts survive', str_contains($safe, 'color:red') && str_contains($safe, 'class="ok x"') && str_contains($safe, 'https://ok.example/x') && str_contains($safe, 'kept text') && str_contains($safe, '{total_payable}') && str_contains($safe, 'data:image/png;base64,iVBORw0KGgo='));
check('links get rel noopener', str_contains($safe, 'rel="noopener noreferrer nofollow"')); eq(paypage_sanitize('   '), '', 'empty stays empty'); check('long input is cut at the limit', mb_strlen(paypage_sanitize(str_repeat('<p>x</p>', 10000))) <= PAYPAGE_MAX * 2);
check('default template is already clean', paypage_sanitize(paypage_default()) !== '' && !str_contains(paypage_sanitize(paypage_default()), '<script') && str_contains(paypage_sanitize(paypage_default()), '{pay_button}'));
$vars = ['app_name' => '<b>App</b>', 'payer_name' => '{app_name}"><script>x</script>', 'logo_url' => 'javascript:alert(1)', 'return_link' => 'https://ok.example/r', 'total_payable' => '₹10'];
$filled = paypage_fill(paypage_sanitize('<p title="{payer_name}">{app_name} {payer_name} {total_payable}<img src="{logo_url}"><a href="{return_link}">back</a>{nope}</p>'), $vars, '[BTN]'); check('parameter values are HTML-escaped', !str_contains($filled, '<script') && str_contains($filled, '&lt;b&gt;App&lt;/b&gt;'));
check('a value cannot inject another parameter', str_contains($filled, '&quot;&gt;&lt;script&gt;') && substr_count($filled, '&lt;b&gt;App&lt;/b&gt;') === 1); check('unsafe URL parameter values are blanked', !str_contains($filled, 'javascript:')); check('safe URL parameter works, unknown stays literal', str_contains($filled, 'href="https://ok.example/r"') && str_contains($filled, '{nope}'));
check('pay_button is replaced by what the server passes', str_contains(paypage_fill('<div>{pay_button}</div>', [], '[BTN]'), '[BTN]')); eq(paypage_unknown_params('{amount} {zzz} {app_name}'), ['zzz'], 'unknown parameters are listed');
eq(paypage_current(), paypage_default(), 'default is used until saved'); eq(paypage_versions(), [], 'no versions yet'); check('payment page is not sent to the gateway by default', !paypage_enabled() && paypage_extra(['id' => 1], ['name' => 'x']) === []);
throws(fn() => paypage_save('<p>Hello there</p>', $adm), 'amount', 'a template must show the amount'); throws(fn() => paypage_save('<script>x</script>', $adm), 'empty', 'a template with only unsafe content is refused'); throws(fn() => paypage_save(str_repeat('a', PAYPAGE_MAX + 1), $adm), 'too long', 'oversize refused');
paypage_save('<h2>{charge_title}</h2><p>Pay {total_payable} <b onclick="x">now</b></p>{pay_button}', $adm, 'v1'); $v = paypage_versions(); eq(count($v), 1, 'save creates a version'); check('stored HTML is the sanitised one', !str_contains(paypage_current(), 'onclick'));
paypage_save('<h2>{charge_title}</h2><p>Second {amount}</p>', $adm, 'v2'); eq(count(paypage_versions()), 2, 'second version'); $before = count(paypage_versions()); paypage_save('<h2>{charge_title}</h2><p>Second {amount}</p>', $adm); eq(count(paypage_versions()), $before, 'saving the same HTML again adds nothing');
$first = paypage_versions()[1]['id']; paypage_rollback((int) $first, $adm); check('rollback restores the old HTML as a new version', str_contains(paypage_current(), '{total_payable}') && count(paypage_versions()) === 3); throws(fn() => paypage_rollback(99999, $adm), 'does not exist', 'rollback of a missing version fails');
