section('Voice: decisions and fallback');
putenv('ELEVENLABS_API_KEY'); putenv('MFNC_VOICE_MOCK'); $vu = $CU('voice-user@x.test', 'Voice User'); $uvu = one('SELECT * FROM {users} WHERE id=?', [$vu]); $vadm = one('SELECT * FROM {users} WHERE id=?', [$adm]); set_setting('feat_voice_mode', 'paid'); set_setting('el_key', '');
eq(voice_decide($uvu)['engine'], 'browser', 'no key configured: browser voice'); eq(voice_decide($uvu)['why'], 'not_configured', 'and the reason is not_configured'); eq(voice_decide(null)['engine'], 'browser', 'signed out: browser');
$r = voice_tts($uvu, 'Hello **there**, see https://x.test now'); eq($r['engine'], 'browser', 'tts falls back to the browser'); eq($r['text'], 'Hello there, see link now', 'and returns clean speakable text'); check('with the subtle hint, not an error', $r['hint'] === VOICE_HINT && !isset($r['error']));
secret_set('el_key', 'test-el-key'); eq(voice_decide($uvu)['why'], 'not_owned', 'key set but the plugin is not owned: browser'); eq(voice_tts($uvu, 'Hi there')['engine'], 'browser', 'tts uses the browser for a person without the plugin');
check('admins always get ElevenLabs when configured', voice_decide($vadm)['engine'] === 'elevenlabs'); grant_feature($vu, 'voice', 30, 'admin'); eq(voice_decide($uvu)['engine'], 'elevenlabs', 'owning the plugin turns ElevenLabs on');
set_setting('voice_enabled', '0'); eq(voice_decide($uvu)['why'], 'off', 'global off switch'); set_setting('voice_enabled', '1');
$st = voice_status($uvu); eq([$st['tts'], $st['stt']], ['elevenlabs', 'elevenlabs'], 'status for the page'); revoke_feature($vu, 'voice'); $st2 = voice_status($uvu); check('status without the plugin says browser + hint', $st2['tts'] === 'browser' && $st2['hint'] === VOICE_HINT); grant_feature($vu, 'voice', 30, 'admin');
check('long text is cut at a sentence', mb_strlen(voice_clean_text(str_repeat('Hello world. ', 400))) <= VOICE_MAX_TTS_CHARS && str_ends_with(voice_clean_text(str_repeat('Hello world. ', 400)), '.')); eq(voice_clean_text("```code```  \n\n # Title"), 'Title', 'code blocks and markdown are dropped');

section('Voice: ElevenLabs calls (local mock server), cache, metering');
$elp = proc_open(['php', '-S', '127.0.0.1:8098', __DIR__ . '/elevenlabs_mock.php'], [1 => ['file', '/dev/null', 'w'], 2 => ['file', '/dev/null', 'w']], $elpipes); for ($i = 0; $i < 40; $i++) { if (@file_get_contents('http://127.0.0.1:8098/__reset') === 'ok') { break; } usleep(100000); }
putenv('ELEVENLABS_BASE=http://127.0.0.1:8098'); run('DELETE FROM {c_voice_usage}'); $cacheDir = sys_get_temp_dir() . '/mfnc-voice-test'; putenv('MFNC_VOICE_CACHE=' . $cacheDir); @array_map('unlink', glob($cacheDir . '/mfnc-voice/*') ?: []);
$r1 = voice_tts($uvu, 'Your spending is fine this month.'); eq($r1['engine'], 'elevenlabs', 'a real HTTP call to the (mock) API works'); check('returns an audio url and hash', str_contains($r1['url'], '/voice/audio') && preg_match('/^[a-f0-9]{64}$/', $r1['hash']) === 1 && !$r1['cached']);
$mst = json_decode((string) file_get_contents('http://127.0.0.1:8098/__state'), true); eq($mst['tts'], 1, 'the API was called once'); eq($mst['last_text'], 'Your spending is fine this month.', 'with the clean text'); eq($mst['last_voice'], voice_cfg()['voice_id'], 'default voice id used'); eq($mst['last_model'], 'eleven_multilingual_v2', 'and the model');
check('the mp3 is cached on disk', is_file(voice_cache_path($r1['hash'])) && str_starts_with((string) file_get_contents(voice_cache_path($r1['hash'])), 'ID3'));
$r2 = voice_tts($uvu, 'Your spending is fine this month.'); check('same text is served from the cache', $r2['cached'] && $r2['hash'] === $r1['hash']); eq(json_decode((string) file_get_contents('http://127.0.0.1:8098/__state'), true)['tts'], 1, 'and the API is not called again');
eq((int) val("SELECT COUNT(*) FROM {c_voice_usage} WHERE user_id=?", [$vu]), 2, 'both uses are logged'); check('cost is recorded for the real call', (int) val("SELECT COALESCE(SUM(cost_micro),0) FROM {c_voice_usage} WHERE user_id=? AND chars>0", [$vu]) > 0); eq((int) val("SELECT cost_micro FROM {c_voice_usage} WHERE user_id=? ORDER BY id DESC LIMIT 1", [$vu]), 0, 'a cached use costs nothing');
$hdrs = voice_usage_today($vu); eq($hdrs['chars'], 66, 'daily characters add up');
set_setting('voice_daily_chars', '60'); eq(voice_decide($uvu)['why'], 'limit', 'the per-person daily limit switches to the browser voice'); eq(voice_tts($uvu, 'Another sentence.')['engine'], 'browser', 'and tts obeys it'); set_setting('voice_daily_chars', '0'); check('0 means no limit', voice_decide($uvu)['engine'] === 'elevenlabs');
set_setting('el_voice_id', 'failvoice'); $f = voice_tts($uvu, 'Provider failure test.'); eq($f['engine'], 'browser', 'a provider failure falls back, no exception'); eq($f['why'], 'provider', 'with the reason logged'); set_setting('el_voice_id', '21m00Tcm4TlvDq8ikWAM');
secret_set('el_key', 'wrong-key'); eq(voice_tts($uvu, 'Bad key test.')['engine'], 'browser', 'a wrong key falls back too'); secret_set('el_key', 'test-el-key');
$sr = voice_stt($uvu, str_repeat('a', 12000), 'audio/webm', 5); eq($sr['engine'], 'elevenlabs', 'speech to text works'); eq($sr['text'], 'hello from the mock', 'returns the transcript'); eq(json_decode((string) file_get_contents('http://127.0.0.1:8098/__state'), true)['last_stt_bytes'], 12000, 'the audio reached the API'); eq(voice_stt($uvu, '', 'audio/webm')['engine'], 'browser', 'empty audio falls back');
eq(voice_stt_bytes($uvu, str_repeat('b', 3000), 'audio/ogg', 3), 'hello from the mock', 'helper for Telegram: stt'); $tb = voice_tts_bytes($uvu, 'Reminder: rent is due tomorrow.', 'opus'); check('helper for Telegram: tts returns audio bytes + mime', is_array($tb) && $tb['mime'] === 'audio/ogg' && strlen($tb['data']) > 100); eq(json_decode((string) file_get_contents('http://127.0.0.1:8098/__state'), true)['last_format'], 'opus_48000_64', 'opus format requested for voice notes');
revoke_feature($vu, 'voice'); eq(voice_tts_bytes($uvu, 'x y z'), null, 'telegram helper returns null (send text) without the plugin'); eq(voice_stt_bytes($uvu, 'abc'), null, 'and for speech to text');
set_setting('feat_voice_mode', 'payg'); set_setting('feat_voice_unit', '0'); set_setting('voice_price_1k', '5000000'); $bal0 = wallet_balance($vu); eq(voice_tts($uvu, 'Short one for payg.')['engine'], 'browser', 'pay as you go with an empty wallet uses the browser voice');
wallet_add($vu, 50000000, 'topup', 'test', 'vtest:1'); $rp = voice_tts($uvu, 'Short one for payg.'); eq($rp['engine'], 'elevenlabs', 'pay as you go with a funded wallet uses ElevenLabs'); eq(wallet_balance($vu), 50000000 - voice_tts_price(19), 'and bills per character'); check('charged amount is reported', $rp['charged_micro'] === voice_tts_price(19));
eq(voice_charge($vadm, 99999, 'x'), 0, 'admins are never billed'); set_setting('feat_voice_mode', 'paid');
// cache trimming
foreach (glob(voice_cache_dir() . '/*') ?: [] as $cf) { @unlink($cf); } for ($i = 0; $i < 6; $i++) { file_put_contents(voice_cache_dir() . '/' . hash('sha256', "old$i") . '.mp3', str_repeat('x', 1000)); touch(voice_cache_dir() . '/' . hash('sha256', "old$i") . '.mp3', time() - 1000 + $i); } $left = count(glob(voice_cache_dir() . '/*.mp3')); $del = voice_cache_trim(3000); check('cache trimming deletes the oldest files first', $del > 0 && count(glob(voice_cache_dir() . '/*.mp3')) < $left); check('and the newest survive, the oldest are gone', is_file(voice_cache_path(hash('sha256', 'old5'))) && !is_file(voice_cache_path(hash('sha256', 'old0'))));
foreach (glob(voice_cache_dir() . '/*') ?: [] as $cf) { @unlink($cf); }
ob_start(); $_SERVER['HTTP_RANGE'] = ''; $_GET['h'] = str_repeat('0', 64); unset($_SESSION); $_SESSION = ['uid' => $vu]; ob_end_clean();

section('Voice: setup request queue and refunds');
$rq = $CU('voice-req@x.test', 'Req User'); $urq = one('SELECT * FROM {users} WHERE id=?', [$rq]); set_setting('voice_setup_fee', '49900'); $fee = 49900 * 10000;
throws(fn() => voice_request_create($rq, 'please'), 'wallet has', 'a request needs the fee in the wallet'); eq((int) val('SELECT COUNT(*) FROM {c_voice_requests}'), 0, 'nothing is filed when the wallet is short'); wallet_add($rq, $fee + 1000000, 'topup', 'test', 'vtest:rq');
$rid = voice_request_create($rq, 'Hindi voice please'); eq(wallet_balance($rq), 1000000, 'the fee left the wallet'); $row = one('SELECT * FROM {c_voice_requests} WHERE id=?', [$rid]); check('request is new with the fee and note', $row['status'] === 'new' && (int) $row['fee_micro'] === $fee && $row['note'] === 'Hindi voice please');
throws(fn() => voice_request_create($rq), 'already', 'only one open request per person'); check('the shop card shows the request status', str_contains(c_plugin_extra(['key' => 'voice', 'state' => 'locked'], $urq), 'with the team'));
voice_request_set($rid, 'in_progress', 'looking'); eq(one('SELECT status FROM {c_voice_requests} WHERE id=?', [$rid])['status'], 'in_progress', 'admin starts it'); secret_set('el_key', ''); throws(fn() => voice_request_set($rid, 'done'), 'API key', 'done needs a configured key'); secret_set('el_key', 'test-el-key');
voice_request_set($rid, 'done', 'all set'); check('done grants the Voice plugin', feature_access($urq, 'voice')['ok']); eq(wallet_balance($rq), 1000000, 'and the money stays collected (no refund)'); throws(fn() => voice_request_set($rid, 'refused'), 'closed', 'a closed request cannot change');
revoke_feature($rq, 'voice'); wallet_add($rq, $fee, 'topup', 'test', 'vtest:rq2'); $rid2 = voice_request_create($rq, 'second'); $before = wallet_balance($rq); voice_request_set($rid2, 'refused', 'sorry'); eq(wallet_balance($rq), $before + $fee, 'a refused request refunds the fee to the wallet'); eq((int) one('SELECT refunded FROM {c_voice_requests} WHERE id=?', [$rid2])['refunded'], 1, 'and is marked refunded');
check('no plugin granted on refusal', !feature_access($urq, 'voice')['ok']); check('refund recorded once in the ledger', (int) val("SELECT COUNT(*) FROM {wallet_ledger} WHERE user_id=? AND ref=?", [$rq, 'voicereq-refund:' . $rid2]) === 1);
wallet_add($rq, 0, 'adjust', 'noop', 'voicereq-refund:' . $rid2); eq(wallet_balance($rq), $before + $fee, 'the refund cannot be applied twice'); set_setting('voice_setup_fee', '0'); $rid3 = voice_request_create($rq, 'free one'); check('a zero fee is a free request', $rid3 > 0 && (int) one('SELECT fee_micro FROM {c_voice_requests} WHERE id=?', [$rid3])['fee_micro'] === 0);
$sd = voice_stats(); check('admin dashboard numbers exist', $sd['calls'] >= 3 && $sd['cost_micro'] > 0 && isset($sd['top'][0]['name']));
$_POST = ['voice_enabled' => '1', 'el_voice_id' => 'bad id!', 'voice_setup_fee' => '10']; throws(fn() => do_admin_voice_save($vadm), 'voice ID', 'admin settings validate the voice id'); $_POST = ['voice_enabled' => '1', 'el_voice_id' => 'abcDEF123456', 'el_key' => 'sk-new-key', 'voice_cache_mb' => '50', 'voice_price_1k' => '5', 'voice_cost_1k' => '15', 'voice_stt_price_min' => '3', 'voice_stt_cost_min' => '2.5', 'voice_daily_chars' => '1000', 'voice_daily_stt_sec' => '60', 'voice_setup_fee' => '499', 'voice_setup_days' => '15'];
do_admin_voice_save($vadm); eq(voice_cfg()['voice_id'], 'abcDEF123456', 'admin saves the voice id'); eq(voice_cfg()['key'], 'sk-new-key', 'and the key (decrypts)'); check('the key is stored encrypted', str_starts_with(site_setting('el_key'), 'v1:') && !str_contains(site_setting('el_key'), 'sk-new-key')); eq(voice_cfg()['price_1k'], 5000000, 'prices parse to micro-rupees');
putenv('ELEVENLABS_API_KEY=env-key'); eq(voice_cfg()['key'], 'env-key', 'the environment variable wins over the saved key'); putenv('ELEVENLABS_API_KEY'); putenv('ELEVENLABS_BASE'); putenv('MFNC_VOICE_CACHE'); set_setting('el_key', ''); proc_terminate($elp); proc_close($elp);
putenv('MFNC_VOICE_MOCK=1'); eq(voice_decide($vadm)['engine'], 'elevenlabs', 'mock mode counts as configured'); $m1 = voice_tts($vadm, 'Mock mode sentence.'); eq($m1['engine'], 'elevenlabs', 'mock mode makes audio without a key'); check('mock mp3 looks like mp3', str_starts_with(voice_mock_mp3('x'), 'ID3')); eq(voice_stt($vadm, 'abcdef')['text'], 'Mock transcription of 6 bytes', 'mock stt'); putenv('MFNC_VOICE_MOCK');

section('AI Layout: defaults, normalisation, operations');
$lo = $CU('layout-user@x.test', 'Layla Layout'); load_demo_data($lo); $ulo = one('SELECT * FROM {users} WHERE id=?', [$lo]); set_setting('feat_ai_layout_mode', 'free'); set_setting('feat_ai_mode', 'free'); set_setting('ai_enabled', '1'); putenv('MFNC_AI_MOCK=1'); run('DELETE FROM {c_layouts}');
$dd = lw_default_layout('desktop'); $dm = lw_default_layout('mobile'); eq(array_column(array_filter($dd['widgets'], fn($w) => $w['visible']), 'id'), ['balance', 'glance', 'limit', 'tip', 'cost', 'health', 'goals', 'trend', 'bva', 'obligations', 'accounts', 'quick_actions', 'quick_payment', 'history', 'milestones'], 'default desktop widgets are today\'s dashboard, in order');
eq(array_slice(array_column($dm['widgets'], 'id'), 0, 3), ['m_actions', 'm_recent', 'balance'], 'default phone layout starts with the quick-add sheet'); check('defaults are valid and stable', lw_is_default($dd, 'desktop') && lw_is_default($dm, 'mobile'));
$ctx = lw_ctx($ulo); $html = lw_render_page($ulo, $ctx); check('the default page renders every original section', str_contains($html, 'aria-label="Balance overview"') && str_contains($html, 'aria-label="At a glance"') && str_contains($html, 'Monthly spending limit') && str_contains($html, 'Goal tracker') && str_contains($html, 'Upcoming obligations') && str_contains($html, 'aria-label="Accounts"') && str_contains($html, 'Quick payment') && str_contains($html, 'Transaction history') && str_contains($html, 'Savings milestones'));
check('default has no phone sheet inside the grid (the page prints it)', !str_contains($html, 'data-lw="m_actions"') && lw_page_sheet($ulo, $ctx) !== '' && str_contains(lw_page_sheet($ulo, $ctx), 'm-sheet'));
check('accounts, quick actions and quick payment share one card', substr_count($html, 'data-lw-group="acct"') === 1);
$n = lw_normalize(['widgets' => [['id' => 'evil', 'visible' => true], ['id' => 'tip', 'size' => 'huge', 'variant' => 'x', 'visible' => 1, 'zone' => 'nowhere'], ['id' => 'tip'], ['id' => 'm_actions', 'visible' => true]], 'theme' => ['font_scale' => 9, 'density' => 'wild', 'contrast' => 'high']], 'desktop'); $tip = $n['widgets'][array_search('tip', array_column($n['widgets'], 'id'))];
check('unknown widgets, duplicate widgets and phone-only widgets are dropped', !in_array('evil', array_column($n['widgets'], 'id')) && count(array_keys(array_column($n['widgets'], 'id'), 'tip')) === 1 && !in_array('m_actions', array_column($n['widgets'], 'id'))); eq([$tip['size'], $tip['variant'], $tip['zone']], ['full', 'default', 'main'], 'invalid size/variant/zone fall back'); eq([$n['theme']['font_scale'], $n['theme']['density'], $n['theme']['contrast']], [1.5, 'comfortable', 'high'], 'theme values are clamped');
check('the critical widget is forced visible', array_values(array_filter($n['widgets'], fn($w) => $w['id'] === 'quick_actions'))[0]['visible']); eq(lw_normalize('garbage', 'mobile')['widgets'][0]['id'], 'm_actions', 'garbage input becomes a valid layout');
[$l, $ap, $rj] = lw_apply_ops($dd, [['op' => 'move', 'widget' => 'quick_payment', 'to' => 'top', 'zone' => 'main'], ['op' => 'resize', 'widget' => 'goals', 'size' => 'full'], ['op' => 'remove', 'widget' => 'tip'], ['op' => 'variant', 'widget' => 'trend', 'variant' => 'bars'], ['op' => 'add', 'widget' => 'advisor', 'size' => 'half']], 'desktop');
eq(count($rj), 0, 'valid operations are all accepted'); $vis = array_column(array_filter($l['widgets'], fn($w) => $w['visible'] && $w['zone'] === 'main'), 'id'); eq($vis[0], 'quick_payment', 'move to top of the main column'); check('tip hidden, advisor shown', !in_array('tip', $vis) && in_array('advisor', $vis)); $byId = array_column($l['widgets'], null, 'id'); eq([$byId['goals']['size'], $byId['trend']['variant'], isset($byId['goals']['md_full'])], ['full', 'bars', false], 'resize and variant');
$ids = array_column($l['widgets'], 'id'); eq(count($ids), count(array_unique($ids)), 'still one entry per widget');
[$l2, , $rj2] = lw_apply_ops($dd, [['op' => 'remove', 'widget' => 'quick_actions'], ['op' => 'nope'], ['op' => 'resize', 'widget' => 'goals', 'size' => 'enormous'], ['op' => 'font_scale', 'value' => 3], ['op' => 'add', 'widget' => 'ghost'], ['op' => 'add', 'widget' => 'm_actions'], ['op' => 'move', 'widget' => 'tip', 'to' => 'before', 'target' => 'ghost'], ['op' => 'variant', 'widget' => 'trend', 'variant' => 'pie'], 'junk', ['op' => 'density', 'value' => 'wild']], 'desktop');
eq(count($rj2), 10, 'every invalid operation is rejected'); check('with reasons', str_contains(json_encode($rj2), 'cannot be removed') && str_contains(json_encode($rj2), 'Unknown widget') && str_contains(json_encode($rj2), '0.9 to 1.5') && str_contains(json_encode($rj2), 'only available on mobile')); check('the layout is unchanged by rejected operations', json_encode($l2) === json_encode($dd));
[$l3, , $r3] = lw_apply_ops(lw_default_layout('mobile'), [['op' => 'remove', 'widget' => 'm_actions']], 'mobile'); check('phone quick-add cannot be removed either', count($r3) === 1); [$l4] = lw_apply_ops($dd, array_map(fn($id) => ['op' => 'remove', 'widget' => $id], array_column($dd['widgets'], 'id')), 'desktop'); check('at least one widget (the critical one) always stays', count(array_filter($l4['widgets'], fn($w) => $w['visible'])) >= 1);
[$e] = lw_apply_ops($dd, [['op' => 'profile', 'name' => 'ease']], 'desktop'); check('ease profile: large text, contrast, simple words, big buttons', $e['theme']['font_scale'] === 1.25 && $e['theme']['contrast'] === 'high' && $e['theme']['simple'] && $e['theme']['big_buttons']); check('ease profile: fewer widgets, all full width', count(array_filter($e['widgets'], fn($w) => $w['visible'])) < 11 && !array_filter($e['widgets'], fn($w) => $w['visible'] && $w['id'] === 'tip') && !array_filter($e['widgets'], fn($w) => $w['visible'] && in_array($w['size'], ['third', 'half'])));
$eh = lw_render_layout($e, $ctx, 'desktop'); check('simple language replaces jargon', str_contains($eh, 'Money you have') && !str_contains($eh, 'Balance overview')); [$ed] = lw_apply_ops($e, [['op' => 'profile', 'name' => 'default']], 'desktop'); check('profile default restores the original', lw_is_default($ed, 'desktop'));
[$c1] = lw_apply_ops($dd, [['op' => 'density', 'value' => 'compact'], ['op' => 'font_scale', 'value' => 1.3]], 'desktop'); [$cls, $css] = lw_theme_attrs($c1['theme']); check('theme becomes classes and a root font-size rule (no free CSS)', str_contains($cls, 'lw-compact') && $css === 'html{font-size:130%}');
foreach (['third' => 'lw-third', 'half' => 'lw-half'] as $sz => $cl) { check("size $sz becomes class $cl", str_contains(lw_render_layout($dd, $ctx, 'desktop'), $cl)); }
[$bars] = lw_apply_ops($dd, [['op' => 'variant', 'widget' => 'trend', 'variant' => 'bars'], ['op' => 'variant', 'widget' => 'balance', 'variant' => 'minimal'], ['op' => 'variant', 'widget' => 'history', 'variant' => 'compact']], 'desktop'); $bh = lw_render_layout($bars, $ctx, 'desktop'); check('variants change the real output', substr_count($bh, '<svg') < substr_count(lw_render_layout($dd, $ctx, 'desktop'), '<svg') + 3 && !str_contains(lw_widget_html('balance', ['variant' => 'minimal'], $ctx, false), 'stat-trio'));

section('AI Layout: backups, restore, reset, plan gate');
eq(lw_backups($lo, 'desktop'), [], 'no backups yet'); eq(lw_get($lo, 'desktop'), $dd, 'a new person gets the default'); $b1 = lw_save($lo, 'desktop', $l, 'first change'); eq(count(lw_backups($lo, 'desktop')), 1, 'saving stores a backup of what was there first'); $bk = one('SELECT * FROM {c_layout_backups} WHERE id=?', [$b1]); check('the backup holds the previous (default) layout', lw_is_default(json_decode($bk['data'], true), 'desktop'));
eq(lw_get($lo, 'desktop')['widgets'][0]['id'], 'quick_payment', 'the saved layout is what the page uses'); eq(lw_get($lo, 'mobile'), $dm, 'the phone layout is separate and untouched'); lw_save($lo, 'desktop', $c1, 'second change'); eq(count(lw_backups($lo, 'desktop')), 2, 'every change adds a backup');
$dev = lw_restore($lo, $b1); eq($dev, 'desktop', 'restore returns the device'); check('restore brings the old layout back', lw_is_default(lw_get($lo, 'desktop'), 'desktop')); eq(count(lw_backups($lo, 'desktop')), 3, 'and first backs up what was current');
$other = $CU('layout-other@x.test'); throws(fn() => lw_restore($other, $b1), 'does not exist', "nobody can restore another person's backup"); throws(fn() => lw_backup_delete($other, $b1), 'does not exist', 'or delete it'); lw_backup_delete($lo, $b1); eq(count(lw_backups($lo, 'desktop')), 2, 'a backup can be deleted');
set_setting('layout_backup_limit', '3'); for ($i = 0; $i < 6; $i++) { lw_save($lo, 'desktop', $i % 2 ? $dd : $c1, "change $i"); } eq(count(lw_backups($lo, 'desktop')), 3, 'old automatic backups are pruned to the limit'); lw_backup($lo, 'desktop', 'keep me', 'manual'); lw_save($lo, 'desktop', $dd, 'x'); lw_save($lo, 'desktop', $c1, 'y'); check('manual backups outlive automatic ones', in_array('keep me', array_column(lw_backups($lo, 'desktop'), 'label'))); set_setting('layout_backup_limit', '20');
lw_save($lo, 'desktop', $c1, 'pre reset'); lw_reset($lo, 'desktop'); check('reset to default restores it and keeps a backup', lw_is_default(lw_get($lo, 'desktop'), 'desktop') && lw_backups($lo, 'desktop')[0]['label'] === 'Before reset to default');
lw_save($lo, 'desktop', $c1, 'custom'); set_setting('feat_ai_layout_mode', 'paid'); eq(lw_get($lo, 'desktop'), $dd, 'without the plugin the default is shown even if a layout was saved'); eq(lw_get($lo, 'desktop', true)['theme']['density'], 'compact', 'and the saved layout is kept for when it returns'); grant_feature($lo, 'ai_layout', 30, 'admin'); eq(lw_get($lo, 'desktop')['theme']['density'], 'compact', 'buying the plugin brings it back'); set_setting('feat_ai_layout_mode', 'free');
$pg = lw_render_page($ulo, $ctx); check('a customised page renders desktop and phone layouts, switched by CSS', str_contains($pg, 'max-lg:hidden') && str_contains($pg, 'lg:hidden') && str_contains($pg, '<style>@media (min-width:1024px)'));
lw_reset($lo, 'desktop');

section('AI Layout: drafts, undo/redo, device awareness');
$row = lw_draft_open($lo, 'desktop'); $row2 = lw_draft_open($lo, 'desktop'); eq($row['id'], $row2['id'], 'the same draft is reused'); $rowm = lw_draft_open($lo, 'mobile'); check('the phone has its own draft', $rowm['id'] !== $row['id'] && $rowm['device'] === 'mobile');
eq(lw_device_param('mobile'), 'mobile', 'client hint: mobile'); eq(lw_device_param('desktop'), 'desktop', 'client hint: desktop'); $_SERVER['HTTP_USER_AGENT'] = 'Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) Mobile/15E148'; eq(lw_device_param(null), 'mobile', 'no hint: a phone user agent means mobile'); $_SERVER['HTTP_USER_AGENT'] = 'Mozilla/5.0 (X11; Linux x86_64)'; eq(lw_device_param('tablet'), 'desktop', 'junk hints fall back to the user agent'); unset($_SERVER['HTTP_USER_AGENT']);
[$nl] = lw_apply_ops(lw_draft_layout($row), [['op' => 'remove', 'widget' => 'health']], 'desktop'); lw_draft_set($row, $nl); $row = lw_draft_row($lo, (int) $row['id']); check('draft changes, live layout does not', !lw_draft_layout($row)['widgets'][5]['visible'] && lw_is_default(lw_get($lo, 'desktop'), 'desktop'));
$st = lw_state($ulo, $row); check('state says dirty, undoable, with a preview url', $st['dirty'] && $st['can_undo'] && !$st['can_redo'] && str_contains($st['preview'], '/layout/preview')); lw_draft_undo($row); $row = lw_draft_row($lo, (int) $row['id']); check('undo restores', lw_is_default(lw_draft_layout($row), 'desktop') && lw_state($ulo, $row)['can_redo']); lw_draft_redo($row); $row = lw_draft_row($lo, (int) $row['id']); check('redo re-applies', !lw_draft_layout($row)['widgets'][5]['visible']); throws(fn() => lw_draft_redo($row), 'Nothing to redo', 'redo past the end');
lw_draft_reset_to_live($row); $row = lw_draft_row($lo, (int) $row['id']); check('discard goes back to the live layout', lw_is_default(lw_draft_layout($row), 'desktop') && !lw_state($ulo, $row)['dirty']); throws(fn() => lw_draft_row($other, (int) $row['id']), 'gone', "another person's draft is not reachable");
lw_save($lo, 'desktop', lw_apply_ops($dd, [['op' => 'remove', 'widget' => 'tip'], ['op' => 'move', 'widget' => 'goals', 'to' => 'top']], 'desktop')[0], 'for mirror'); [$mir, $ma] = lw_apply_ops($dm, [['op' => 'mirror', 'from' => 'desktop']], 'mobile', $lo); $mids = array_column(array_filter($mir['widgets'], fn($w) => $w['visible']), 'id'); check('mirror copies desktop to the phone: order and visibility, quick-add first', $mids[0] === 'm_actions' && !in_array('tip', $mids) && array_search('goals', $mids) < array_search('balance', $mids)); eq($ma, ['Copied the desktop layout and adapted it for mobile'], 'and says so');
[$back] = lw_apply_ops($mir, [['op' => 'mirror', 'from' => 'mobile']], 'desktop', $lo); check('mirror to desktop yields a valid desktop layout', count(array_filter($back['widgets'], fn($w) => $w['id'] === 'm_actions')) === 0); lw_reset($lo, 'desktop');

section('AI Layout: assistant, verify loop (mock model)');
run('DELETE FROM {ai_usage}'); $ev = []; $emit = function ($e) use (&$ev) { $ev[] = $e; }; $row = lw_draft_open($lo, 'desktop'); lw_draft_reset_to_live($row);
lw_ai_turn($ulo, (int) $row['id'], 'Put my bills first', $emit); $types = array_column($ev, 'type'); check('events: status, steps, snapshot, message, done', in_array('status', $types) && in_array('step', $types) && in_array('snapshot', $types) && in_array('message', $types) && end($types) === 'done');
$msg = array_values(array_filter($ev, fn($e) => $e['type'] === 'message'))[0]; eq($msg['message']['kind'], 'result', 'a verified result'); check('message is built from the verified diff', $msg['message']['changes'] !== [] && str_contains($msg['message']['text'], 'Verified on the preview')); eq($msg['state']['snapshot']['order'][0], 'quick_payment', 'the verified snapshot has the bills widget first'); check('the live layout is still untouched (draft only)', lw_is_default(lw_get($lo, 'desktop'), 'desktop'));
check('tokens were metered through the AI usage log', (int) val('SELECT COUNT(*) FROM {ai_usage} WHERE user_id=?', [$lo]) >= 1); check('the snapshot event carries a state for the live preview', (bool) array_filter($ev, fn($e) => $e['type'] === 'snapshot' && isset($e['state']['preview'])));
$stepLabels = implode('|', array_column(array_filter($ev, fn($e) => $e['type'] === 'step'), 'label')); check('steps name what happened (draft changed, preview rendered)', str_contains($stepLabels, 'Changing the draft'));
$ev = []; $GLOBALS['__lw_mock_fixed'] = 0; lw_ai_turn($ulo, (int) $row['id'], 'flawmock show my goals bigger', $emit); $steps = array_filter($ev, fn($e) => $e['type'] === 'step' && $e['status'] !== 'running' && str_contains($e['label'], 'refused')); check('the first attempt had a rejected operation and the model was told', count($steps) === 1); $m2 = array_values(array_filter($ev, fn($e) => $e['type'] === 'message'))[0]['message'];
check('the model fixed it on the second round (goals changed)', (bool) array_filter($m2['changes'], fn($c) => str_contains($c, 'Goal tracker'))); check('and the final message reports the refusal honestly', in_array('Unknown widget "nonexistent". Call list_widgets for the valid ids.', $m2['refused']));
$ev = []; lw_ai_turn($ulo, (int) $row['id'], 'make it easy for my mother', $emit); $m3 = array_values(array_filter($ev, fn($e) => $e['type'] === 'message'))[0]; check('tweak works on the same draft (ease profile on top)', $m3['state']['layout']['theme']['big_buttons'] === true && $m3['state']['snapshot']['order'] !== []); check('and the earlier change is still there (bills first became part of draft history)', $m3['state']['can_undo']);
$ev = []; lw_ai_turn($ulo, (int) $row['id'], 'what is the weather', $emit); $m4 = array_values(array_filter($ev, fn($e) => $e['type'] === 'message'))[0]['message']; eq($m4['kind'], 'note', 'a request it cannot map makes no changes and just talks'); eq($m4['changes'], [], 'no changes claimed');
lw_draft_undo(lw_draft_row($lo, (int) $row['id'])); $ev = []; $rowx = lw_draft_open($lo, 'mobile'); lw_draft_reset_to_live($rowx); lw_ai_turn($ulo, (int) $rowx['id'], 'hide the tips and make text bigger', $emit); $m5 = array_values(array_filter($ev, fn($e) => $e['type'] === 'message'))[0]; eq($m5['state']['device'], 'mobile', 'a phone draft edits the phone layout'); check('desktop live layout still untouched', lw_is_default(lw_get($lo, 'desktop'), 'desktop') && lw_is_default(lw_get($lo, 'mobile'), 'mobile'));
$tt = []; $lw = lw_tool_result($ulo, $rowx, 'list_widgets', [], $tt); check('phone list includes phone-only widgets, desktop list does not', in_array('m_actions', array_column($lw['widgets'], 'id')) && !in_array('m_actions', array_column(lw_tool_result($ulo, $row, 'list_widgets', [], $tt)['widgets'], 'id')));
$snapT = lw_tool_result($ulo, $row, 'preview_layout', [], $tt)['snapshot']; check('snapshot has ordered widgets with real visible text and sizes', isset($snapT['widgets'][0]['text']) && $snapT['visible_count'] > 5 && str_contains(json_encode($snapT['widgets'], JSON_UNESCAPED_UNICODE), '₹'));
$gl = lw_default_layout('desktop'); $gl['theme']['font_scale'] = 1.4; $gl['widgets'][array_search('goals', array_column($gl['widgets'], 'id'))]['size'] = 'quarter'; $gs = lw_snapshot($gl, $ctx, 'desktop'); check('snapshot warns about overflow risk for big text in a narrow widget', (bool) array_filter($gs['warnings'], fn($w) => str_contains($w, 'overflow')));
$emptyU = $CU('layout-empty@x.test'); $ge = lw_snapshot(lw_default_layout('desktop'), lw_ctx(one('SELECT * FROM {users} WHERE id=?', [$emptyU])), 'desktop'); check('snapshot warns about empty widgets for a brand-new account', (bool) array_filter($ge['warnings'], fn($w) => str_contains($w, 'empty')));
$png = lw_wire_png($dd, 'desktop'); check('wireframe PNG renders', str_starts_with($png, "\x89PNG") && getimagesizefromstring($png)[0] === 760); check('and for phones', getimagesizefromstring(lw_wire_png($dm, 'mobile'))[0] === 300);
set_setting('feat_ai_layout_mode', 'paid'); $ev = []; lw_ai_turn($other ? one('SELECT * FROM {users} WHERE id=?', [$other]) : $ulo, (int) $row['id'], 'x', $emit); check('AI turn is refused without the plugin (server side)', end($ev)['type'] === 'error' || $ev[0]['type'] === 'error'); set_setting('feat_ai_layout_mode', 'free');
$ev = []; set_setting('ai_enabled', '0'); lw_ai_turn($ulo, (int) $row['id'], 'put my bills first', $emit); eq($ev[0]['type'], 'error', 'AI switched off: honest error, no changes'); set_setting('ai_enabled', '1'); putenv('MFNC_AI_MOCK');
$ptmp = null; $GLOBALS['__user'] = $ulo; $_GET = ['draft' => (string) $row['id']]; ob_start(); page_layout_preview(); $ph = (string) ob_get_clean(); check('preview page renders the draft with the real widgets and no scripts', str_contains($ph, 'data-preview="1"') && str_contains($ph, 'data-lw="balance"') && !str_contains($ph, '<script')); unset($GLOBALS['__user']); $_GET = [];

// ---- round 3 tester regressions ----
section('Tester round 3');
check('QR contrast helper: white fails, the default green passes', qr_contrast_white('#ffffff') < 3 && qr_contrast_white('#0b3d2e') > 7 && qr_contrast_white('#aaaaaa') < 3);
throws(fn() => share_validate(['title' => 'T', 'widgets' => ['summary'], 'color' => '#eeeeee']), 'too light', 'a pale QR colour that cannot be scanned is refused');
check('a dark QR colour is accepted', share_validate(['title' => 'T', 'widgets' => ['summary'], 'color' => '#1a237e'])['color'] === '#1a237e');
$pbtn = '<a class="pay" href="https://pay.example/1" style="x">PAY</a>';
foreach (['<img src="https://a.b/x.png" alt="{pay_button}<b>">', '<a href="{pay_button}">x</a>', '<img src="{pay_button}">', '<a href="https://ok.example/{pay_button}">x</a>', '<img alt="%7Bpay_button%7D">'] as $badTpl) {
    check('{pay_button} never lands inside an attribute: ' . substr($badTpl, 0, 40), !str_contains(paypage_fill(paypage_sanitize($badTpl), ['amount' => '1'], $pbtn), 'class="pay"'));
}
check('{pay_button} still works as text', str_contains(paypage_fill(paypage_sanitize('<div>{pay_button}</div>'), [], $pbtn), 'class="pay"'));
$once = paypage_sanitize('<img src="{logo_url}" alt="x"><a href="{return_link}">b</a>'); $twice = paypage_sanitize($once);
check('placeholders in src/href survive a second sanitise (saved templates are re-sanitised on every render)', $once === $twice && str_contains($twice, 'src="{logo_url}"') && str_contains($twice, 'href="{return_link}"'), $twice);
check('and the filled page gets the real URLs', str_contains(paypage_fill($twice, ['logo_url' => 'https://a.b/l.png', 'return_link' => 'https://a.b/r'], ''), 'src="https://a.b/l.png"'));
check('voice cache hash is keyed (not a plain sha256 of the text)', voice_hash('Hello') !== hash('sha256', implode('|', [voice_cfg()['voice_id'], voice_cfg()['model'], 'mp3', voice_mock() ? 'mock' : 'live', 'Hello'])) && strlen(voice_hash('Hello')) === 64);
check('voice text loses control characters', !preg_match('/[\x00-\x08]/', voice_clean_text("a\x00b\x01 c")));
$pp = new MfPdf(); $pp->AddPage(); $pp->f('', 9); $pp->SetXY(14, 20); $pp->Cell(30, 6, $pp->t(str_repeat('W', 80)), 0, 0); check('PDF cells never run past their width (truncated with ...)', $pp->GetX() - 14 <= 30.01 && str_starts_with($pp->Output('S'), '%PDF'));
check('share title/message lose control characters', share_validate(['title' => "a\x00b\r\nc", 'message' => "x\x00y", 'widgets' => ['summary']])['title'] === 'a b c' && share_validate(['title' => 'T', 'message' => "x\x00y", 'widgets' => ['summary']])['message'] === 'xy');
$tt = lw_default_layout('mobile'); $tt['theme']['font_scale'] = 1.4; $tt = lw_normalize($tt, 'mobile'); check('large text adds the lw-xl class (tiles become one column)', str_contains(lw_theme_attrs($tt['theme'])[0], 'lw-xl'));
$bad = lw_normalize(['widgets' => [['id' => ['a']], ['id' => 'balance', 'size' => ['x']], null, 5]], 'desktop'); check('tampered layout JSON with non-string ids is cleaned without warnings', count($bad['widgets']) === count(lw_default_layout('desktop')['widgets']));
